<script lang="ts">
 import {onMount} from 'svelte';import Icon from './Icon.svelte';
 export let scope:'media'|'works';export let id:string;export let title:string;export let current:string|undefined;export let token:string;export let saved:()=>Promise<void>;export let close:()=>void;
 type Option={ref:string;image:string;language:string;width:number;height:number};
 let dialog:HTMLDialogElement;let options:Option[]=[];let custom='';let warning='';let error='';let loading=true;let saving=false;let selected:Option|undefined;let file:File|undefined;let preview='';let mode:'current'|'choice'|'upload'|'automatic'='current';let failed:Record<string,boolean>={};let alive=true;
 const controller=new AbortController();const endpoint=`/api/v1/posters/${scope}/${id}`;
 onMount(()=>{dialog.showModal();void load();return()=>{alive=false;controller.abort();if(preview)URL.revokeObjectURL(preview);};});
 async function load(){try{const r=await fetch(endpoint+'/options',{signal:controller.signal});const data=await r.json();if(!r.ok)throw new Error(data.error);if(alive){options=data.items;custom=data.custom;warning=data.warning;}}catch(e){if(alive)error=e instanceof Error?e.message:'Propositions indisponibles.';}finally{if(alive)loading=false;}}
 function upload(event:Event){const input=event.currentTarget as HTMLInputElement;const candidate=input.files?.[0];if(!candidate)return;error='';if(candidate.size>8*1024*1024){error='Choisissez une image de 8 Mo maximum.';input.value='';return;}if(preview)URL.revokeObjectURL(preview);file=candidate;preview=URL.createObjectURL(candidate);mode='upload';selected=undefined;}
 async function save(){if(saving||mode==='current')return;saving=true;error='';try{const r=await fetch(endpoint,{method:mode==='automatic'?'DELETE':mode==='upload'?'PUT':'POST',headers:{'X-Mosaune-Token':token,...(mode==='choice'?{'Content-Type':'application/json'}:{})},body:mode==='upload'?file:mode==='choice'?JSON.stringify({ref:selected?.ref}):undefined,signal:controller.signal});if(!r.ok)throw new Error((await r.json()).error||'Affiche non enregistrée.');await saved();if(alive)dialog.close();}catch(e){if(alive)error=e instanceof Error?e.message:'Affiche non enregistrée.';}finally{if(alive)saving=false;}}
 $: shown=mode==='upload'?preview:mode==='choice'?selected?.image:mode==='automatic'?undefined:current;
</script>
<dialog bind:this={dialog} class="media-dialog poster-editor" onclose={close} oncancel={e=>{if(saving)e.preventDefault();}} aria-labelledby="poster-editor-title">
 <div class="dialog-heading"><div><span class="eyebrow">VOTRE REGARD SUR L’HISTOIRE</span><h2 id="poster-editor-title">Choisir l’affiche</h2><p>{title}</p></div><button class="icon-button" disabled={saving} aria-label="Fermer" onclick={()=>dialog.close()}><Icon name="close"/></button></div>
 <div class="poster-layout"><aside class="poster-preview"><div class="poster-preview-image">{#if shown}<img src={shown} alt="Aperçu de l’affiche"/>{:else}<Icon name="films" size={48}/>{/if}</div><strong>{mode==='upload'?'Votre image':mode==='choice'?'Votre sélection':mode==='automatic'?'Affiche automatique':'Affiche actuelle'}</strong><p>{mode==='automatic'?'L’affiche du catalogue sera rétablie après enregistrement.':'Votre choix sera conservé lors des actualisations.'}</p><label class="poster-upload">Importer une image<input type="file" accept="image/jpeg,image/png" disabled={saving} onchange={upload}/></label><small>JPEG ou PNG · 8 Mo maximum</small>{#if custom}<button class="text-action" disabled={saving} onclick={()=>mode='automatic'}>Rétablir l’affiche automatique</button>{/if}</aside>
 <section class="poster-options" aria-label="Affiches proposées"><h3>Les propositions du fournisseur</h3><p>Les affiches en français apparaissent en premier, lorsqu’elles existent.</p>{#if loading}<p role="status">Recherche des affiches… Vous pouvez déjà importer une image.</p>{/if}{#if warning}<p class="notice" role="status">{warning} L’import d’une image reste disponible.</p>{/if}
 <div class="poster-grid">{#each options as option}<button class:chosen={mode==='choice'&&selected?.ref===option.ref} aria-pressed={mode==='choice'&&selected?.ref===option.ref} aria-label={`Choisir cette affiche, ${option.language||'sans texte précisé'}, ${option.width} par ${option.height}`} disabled={saving||failed[option.ref]} onclick={()=>{selected=option;mode='choice';error='';}}>{#if !failed[option.ref]}<img src={option.image} alt="Affiche proposée" loading="lazy" onerror={()=>failed={...failed,[option.ref]:true}}/>{:else}<span class="poster-missing">Image indisponible</span>{/if}<span>{option.language==='fr'?'Français':option.language?option.language.toUpperCase():'Sans langue'} · {option.width} × {option.height}</span></button>{/each}</div>
 {#if !loading&&!options.length&&!warning}<p>Aucune affiche alternative disponible. Vous pouvez importer votre image ; si ce média n’est pas encore identifié, « Corriger l’association » permettra de rechercher sa fiche.</p>{/if}</section></div>
 {#if error}<p class="playback-error" role="alert">{error}</p>{/if}
 <div class="poster-footer"><button class="secondary" disabled={saving} onclick={()=>dialog.close()}>Annuler</button><button class="primary" disabled={saving||mode==='current'||(mode==='upload'&&!file)} onclick={save}>{saving?'Enregistrement…':'Enregistrer l’affiche'}</button></div>
</dialog>
<style>
 .poster-editor{width:min(1080px,94vw);max-height:90vh;padding:1.8rem}.dialog-heading p{margin:.5rem 0;color:var(--m-dialog-heading-p-color)}.poster-layout{display:grid;grid-template-columns:220px minmax(0,1fr);gap:2rem;margin:1.6rem 0}.poster-preview{display:flex;flex-direction:column;align-items:flex-start;gap:.8rem}.poster-preview-image{width:100%;aspect-ratio:2/3;background:var(--m-poster-preview-image-background);border-radius:var(--m-poster-preview-image-border-radius);overflow:hidden;display:grid;place-items:center}.poster-preview-image img{width:100%;height:100%;object-fit:contain}.poster-preview p,.poster-options>p{color:var(--m-poster-preview-p-color);font-size:var(--m-poster-preview-p-font-size);line-height:var(--m-poster-preview-p-line-height)}.poster-preview p{margin:0}.poster-upload{font-size:var(--m-poster-upload-font-size);font-weight:var(--m-poster-upload-font-weight)}.poster-upload input{display:block;max-width:100%;font-size:var(--m-poster-upload-input-font-size);margin-top:.6rem;padding:.5rem}.poster-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(140px,1fr));gap:1rem}.poster-grid button{padding:5px;border:2px solid var(--m-poster-grid-button-border);border-radius:var(--m-poster-grid-button-border-radius);background:var(--m-poster-grid-button-background);text-align:left;overflow:hidden}.poster-grid button.chosen{border-color:var(--m-poster-grid-button-chosen-border-color);background:var(--m-poster-grid-button-chosen-background)}.poster-grid img,.poster-missing{display:block;width:100%;aspect-ratio:2/3;object-fit:cover;border-radius:var(--m-poster-grid-img-border-radius)}.poster-grid button>span{display:block;padding:.55rem .25rem;font-size:var(--m-poster-grid-button-span-font-size)}.poster-footer{display:flex;justify-content:flex-end;gap:1rem;position:sticky;bottom:-1.8rem;background:var(--m-poster-footer-background);padding:1rem 0;border-top:1px solid var(--m-poster-footer-border-top)}.poster-options h3{margin-top:0}small{color:var(--m-small-color)}@media(max-width:640px){.poster-layout{grid-template-columns:1fr}.poster-preview-image{width:150px}.poster-editor{padding:1rem}.poster-footer{bottom:-1rem}.poster-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
</style>
